import { useState } from 'react'
import { Button as AriaButton } from 'react-aria-components'

import { Modal } from '../Modal/Modal'

/**
 * Who something belongs to — a monitor's owner, an alert's assignee — as a picture or as initials.
 *
 * ```tsx
 * <Avatar alt="Ada Lovelace" src="/ada.png" />
 * <Avatar alt="Ada Lovelace" />              // initials, when there is no picture
 * <Avatar alt="fra1" color="primary" />      // a machine's name works the same way
 * <Avatar alt="Ada Lovelace" src="/ada.png" isPreviewable />
 * ```
 *
 * **This is the fourth component here with nothing in the sheet to copy** — after the date picker, the
 * accordion and the toast. `pulse-replica/` has no avatar, no user chip and nothing person-shaped at all,
 * so every decision below comes from the system's own language rather than from a source file:
 *
 * - **Square, like everything else.** The sheet squares off its buttons and inputs and makes exactly two
 *   exceptions — the checkbox's 2px and the radio's circle. A round avatar would be a third, so it is
 *   `rounded-none`. This is the one place a designer would expect a circle, which is why it is worth
 *   saying out loud rather than leaving to look like an oversight.
 * - **A fill carrying `ink`**, like every other filled control here. The five colours are `Button`'s, so an
 *   avatar cannot drift away from the palette it sits beside.
 * - **Mono, uppercase, letterspaced initials** — the same face every other label in this system wears.
 *
 * **Initials, not an icon.** The fallback is derived from `alt`: the first letter of the first and last
 * words, or the first two letters of a single word — so "Ada Lovelace" is `AL` and "fra1" is `FR`. A
 * generic silhouette would say "somebody" and this is a monitoring system, where *which* somebody is the
 * whole content of the cell.
 *
 * **A broken image falls back to initials rather than to nothing.** That is the state a real dashboard
 * spends most of its life in — an avatar URL that 404s, a service without a picture — and it is checked in
 * the stories with a source that cannot load.
 *
 * **`isPreviewable` changes what the element is, which is why it is opt-in.** Off, this is a `<span>` with
 * `role="img"` — a picture, correctly skipped by the tab order. On, it is a **button** that opens the
 * avatar large in a modal, because a picture that responds to a click has to be reachable by keyboard and
 * announced as something you can press. An avatar in a list or a table cell is decoration, and turning
 * every one of them into a tab stop would be the wrong default.
 */
export interface AvatarProps {
  /** The image. Omit it, or let it fail, and the initials are used. */
  src?: string
  /**
   * The person or thing this stands for. Required, and it is a **name rather than a description** — it
   * becomes the accessible name and the initials, so there is nothing else to give.
   */
  alt: string
  size?: 'sm' | 'md' | 'lg'
  /** `Button`'s palette. `neutral` is the default because most of these are not the interesting one. */
  color?: 'primary' | 'secondary' | 'neutral' | 'success' | 'danger'
  /**
   * Opens the avatar in a modal when it is pressed. The avatar becomes a button, so this changes the
   * element and its place in the tab order — see the note above on why it is off by default.
   */
  isPreviewable?: boolean
  className?: string
}

/** Only `--avatar` is set per colour; the fill and the label both read it, so they cannot disagree. */
const COLORS: Record<NonNullable<AvatarProps['color']>, string> = {
  primary: '[--avatar:var(--color-teal)]',
  secondary: '[--avatar:var(--color-yellow)]',
  neutral: '[--avatar:var(--color-neutral)]',
  success: '[--avatar:var(--color-green)]',
  danger: '[--avatar:var(--color-red)]',
}

const SIZES: Record<NonNullable<AvatarProps['size']>, string> = {
  sm: 'size-6 text-[10px]',
  md: 'size-8 text-[11px]',
  lg: 'size-10 text-[13px]',
}

/**
 * The face in the modal: much larger than any inline size, because the whole point of opening it is to see
 * the picture. `size-56` is 224px — big enough to read a face, small enough to leave the dialog room for
 * the name beneath it.
 */
const PREVIEW_SIZE = 'size-56 text-[56px]'

/**
 * The first letter of the first and last words, or the first two letters of a single one.
 *
 * A name that is only punctuation or spaces has no letters to take, so it gets `?` rather than an empty
 * box — the one case where the fallback has to invent something rather than derive it.
 */
export function initials(name: string) {
  const words = name
    .trim()
    .split(/\s+/)
    .filter((word) => /\S/.test(word))
  if (words.length === 0) return '?'
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase()
  return (words[0][0] + words.at(-1)![0]).toUpperCase()
}

export function Avatar({
  src,
  alt,
  size = 'md',
  color = 'neutral',
  isPreviewable = false,
  className,
}: AvatarProps) {
  const [failed, setFailed] = useState(false)
  const showImage = Boolean(src) && !failed

  /** The fill, the label and the shape — the same in the row and in the modal, at two different sizes. */
  const box = (dimensions: string, extra?: string) =>
    [
      'inline-flex shrink-0 items-center justify-center overflow-hidden rounded-none',
      dimensions,
      COLORS[color],
      // `ink` on the fill, which inverts with the theme — black on the luminous dark accents, white on
      // the deep light ones. Hardcoding either is the mistake the token exists to prevent.
      'bg-(--avatar) font-mono tracking-[0.04em] text-ink uppercase',
      extra,
    ]
      .filter(Boolean)
      .join(' ')

  // The picture, or the initials when there is none to show. Rendered in whichever box is asking for it.
  const face = (
    <>
      {showImage ? (
        <img
          data-slot="avatar-image"
          src={src}
          alt=""
          onError={() => setFailed(true)}
          className="size-full object-cover"
        />
      ) : (
        <span data-slot="avatar-initials" aria-hidden="true">
          {initials(alt)}
        </span>
      )}
    </>
  )

  if (!isPreviewable) {
    return (
      <span
        data-slot="avatar"
        // The wrapper carries the name and the image is decorative, so a screen reader hears "Ada Lovelace"
        // once. Giving both an `alt` announces the same thing twice.
        role="img"
        aria-label={alt}
        className={box(SIZES[size], className)}
      >
        {face}
      </span>
    )
  }

  return (
    <Modal>
      {/* React Aria's own `Button`, not this system's: the styled one brings a fill, a size and a padding,
          and this element is an avatar that happens to be pressable. It also has to be a real button for
          `DialogTrigger` to open the modal from the keyboard. */}
      <AriaButton
        data-slot="avatar"
        // The name alone would not say what pressing it does, so the action is in the label. It is also
        // why the initials are `aria-hidden`: the name is announced once, by the button.
        aria-label={`Preview ${alt}`}
        className={box(SIZES[size], `cursor-pointer ${className ?? ''}`)}
      >
        {face}
      </AriaButton>
      <Modal.Content>
        <Modal.Close />
        <Modal.Title>{alt}</Modal.Title>
        <div className="flex justify-center py-2">
          <span
            data-slot="avatar-preview"
            role="img"
            aria-label={alt}
            className={box(PREVIEW_SIZE)}
          >
            {face}
          </span>
        </div>
      </Modal.Content>
    </Modal>
  )
}

import { createContext, useContext, useId } from 'react'
import {
  Button as AriaButton,
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Heading as AriaHeading,
  Modal as AriaModal,
  ModalOverlay as AriaModalOverlay,
  Text as AriaText,
} from 'react-aria-components'
import type {
  ButtonProps as AriaButtonProps,
  DialogProps as AriaDialogProps,
  DialogTriggerProps as AriaDialogTriggerProps,
  HeadingProps as AriaHeadingProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

/**
 * The scrim. **The one place in this system where the palette deliberately does not reach.**
 *
 * A scrim's job is to push the page back, which means it has to *darken* — and there is no token
 * that darkens in both themes. `--color-ink` is black in the dark theme and white in the light one,
 * so it would haze a white page white and separate nothing; `--color-base` is black in one and white
 * in the other for the same reason. `black/50` is Tailwind's own, is the same in both themes by
 * design, and says exactly what it is.
 */
const OVERLAY = [
  'fixed inset-0 z-50 grid place-items-center overflow-y-auto p-4',
  'bg-black/50',
].join(' ')

/**
 * The sheet's `.ds-panel`, with an edge: a dialog floats over a page, so it needs the same separation
 * the tooltip and the toast do — its own panel, and a hairline to say where it ends.
 */
const DIALOG = [
  'relative w-full max-w-md',
  'border border-line-strong bg-panel p-6',
  'outline-none',
].join(' ')

/** The sheet's `.ds-panel-title`: 18px/600, measured off its Page Check reference. */
export const DIALOG_TITLE =
  'm-0 text-[18px] font-semibold tracking-[0.01em] text-fg'

export const DIALOG_DESCRIPTION = 'mt-2 text-[13px] leading-[1.5] text-fg/70'

export const DIALOG_FOOTER = 'mt-6 flex items-center justify-end gap-3'

/** The same dismiss control the toast draws, for the same reason: it is the one that is often missed. */
export const DIALOG_CLOSE = [
  'absolute end-4 top-4 grid size-5 cursor-pointer place-items-center',
  'text-fg/45',
  'transition-colors duration-[120ms] ease-pulse',
  'data-[hovered]:text-fg',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-2',
  'data-[focus-visible]:outline-teal',
].join(' ')

export interface ModalProps extends Omit<
  AriaDialogTriggerProps,
  'children' | 'className' | 'isOpen' | 'defaultOpen' | 'onOpenChange'
> {
  /**
   * Whether the dialog is open. This is a React Aria prop on the trigger — controlled state, so pass
   * `onOpenChange` with it.
   */
  isOpen?: AriaDialogTriggerProps['isOpen']
  /** Whether the dialog starts open, for uncontrolled use. */
  defaultOpen?: AriaDialogTriggerProps['defaultOpen']
  /** Called when the dialog asks to open or close. */
  onOpenChange?: AriaDialogTriggerProps['onOpenChange']

  /** The trigger, then a `Modal.Content`. */
  children?: React.ReactNode
}

export interface ModalContentProps extends Omit<
  AriaDialogProps,
  'children' | 'className'
> {
  className?: string
  /** A `Modal.Title`, the body, and a `Modal.Footer`. */
  children?: React.ReactNode
}

export interface ModalTitleProps extends AriaHeadingProps {
  children?: React.ReactNode
}

export interface ModalDescriptionProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface ModalFooterProps {
  className?: string
  children?: React.ReactNode
}

export interface ModalCloseProps extends Omit<
  AriaButtonProps,
  'children' | 'className' | 'slot'
> {
  className?: string
  children?: React.ReactNode
}

/**
 * The description's id, shared between the dialog and the `Text` inside it. React Aria wires the
 * **title** to the dialog for you — `aria-labelledby` appears on its own — but it does not wire the
 * description, and a description nobody is pointed at is decoration. The id is generated here and
 * passed down rather than written by the consumer, who would have to keep two things in step.
 */
const DescriptionId = createContext<string | undefined>(undefined)

/**
 * The dialog's surface, its scrim and its placement, in one slot. Use it as `Modal.Content`, as the
 * second child of a `Modal`.
 *
 * Exported as `ModalContent` only so tooling can resolve it; consume the compound form
 * `Modal.Content`.
 */
export function ModalContent({
  className,
  children,
  ...props
}: ModalContentProps) {
  const descriptionId = useId()
  return (
    <AriaModalOverlay data-slot="modal" className={OVERLAY} isDismissable>
      <AriaModal className="w-full max-w-md">
        <DescriptionId.Provider value={descriptionId}>
          <AriaDialog
            // Points at the description whether or not one was passed. A dialog with a dangling
            // `aria-describedby` is a smaller thing than a description nobody reads.
            aria-describedby={descriptionId}
            className={[DIALOG, className].filter(Boolean).join(' ')}
            {...props}
          >
            {children}
          </AriaDialog>
        </DescriptionId.Provider>
      </AriaModal>
    </AriaModalOverlay>
  )
}

/**
 * What the dialog is about. Use it as `Modal.Title`. It is the sheet's `.ds-panel-title`, and it is
 * what names the dialog — React Aria wires it to the dialog's `aria-labelledby`, so the title is not
 * decoration.
 *
 * Exported as `ModalTitle` only so tooling can resolve it; consume the compound form `Modal.Title`.
 */
export function ModalTitle({ className, children, ...props }: ModalTitleProps) {
  return (
    <AriaHeading
      slot="title"
      className={[DIALOG_TITLE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaHeading>
  )
}

/**
 * A sentence under the title. Use it as `Modal.Description` — it becomes the dialog's
 * `aria-describedby`, so a screen reader hears what the dialog is for before it hears the controls.
 *
 * Exported as `ModalDescription` only so tooling can resolve it; consume the compound form
 * `Modal.Description`.
 */
export function ModalDescription({
  className,
  children,
  ...props
}: ModalDescriptionProps) {
  const id = useContext(DescriptionId)
  return (
    <AriaText
      id={id}
      slot="description"
      className={[DIALOG_DESCRIPTION, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The actions, right-aligned. Use it as `Modal.Footer`.
 *
 * Exported as `ModalFooter` only so tooling can resolve it; consume the compound form
 * `Modal.Footer`.
 */
export function ModalFooter({ className, children }: ModalFooterProps) {
  return (
    <div className={[DIALOG_FOOTER, className].filter(Boolean).join(' ')}>
      {children}
    </div>
  )
}

/**
 * The **×** in the corner. Use it as `Modal.Close` — it is absolutely positioned, so it belongs to
 * the dialog rather than to a footer.
 *
 * Its `slot="close"` is what tells React Aria it is a dismiss control, and that attribute is the
 * whole mechanism: putting it on **any** button closes the dialog. A footer that says "Cancel"
 * rather than "×" therefore wants a plain `Button` with the same `slot`, not this — a first version of
 * the story used `Modal.Close` in its footer and the word flew to the top-right corner, because
 * `position: absolute` goes where it is told.
 *
 * Exported as `ModalClose` only so tooling can resolve it; consume the compound form
 * `Modal.Close`.
 */
export function ModalClose({ className, children, ...props }: ModalCloseProps) {
  return (
    <AriaButton
      slot="close"
      aria-label="Close"
      className={[DIALOG_CLOSE, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? (
        <svg
          viewBox="0 0 10 10"
          fill="none"
          aria-hidden="true"
          className="size-2.5"
        >
          <path
            d="M1 1L9 9M9 1L1 9"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      )}
    </AriaButton>
  )
}

/**
 * Styled element. Not exported — `Modal` below is the public symbol, and docgen reads the JSDoc from
 * the *exported* declaration, not this one.
 */
function ModalRoot({ children, ...props }: ModalProps) {
  return <AriaDialogTrigger {...props}>{children}</AriaDialogTrigger>
}

/**
 * A dialog over the page: a short task that needs an answer before the page can be used again.
 *
 * ```tsx
 * <Modal>
 *   <Button>New monitor</Button>
 *   <Modal.Content>
 *     <Modal.Title>New monitor</Modal.Title>
 *     <Modal.Description>It starts checking as soon as you save.</Modal.Description>
 *     <Modal.Footer>
 *       <Modal.Close>Cancel</Modal.Close>
 *       <Button variant="primary">Save</Button>
 *     </Modal.Footer>
 *   </Modal.Content>
 * </Modal>
 * ```
 *
 * **A modal is a demand, so it should be rare.** It takes the page away, traps focus, and stops
 * anyone reading behind it — which is the right trade for a decision that has to be made now, and
 * the wrong one for a form someone might want to consult the page while filling in. A `Popover` is
 * the same dialog without that cost, and the sheet's own menus are popovers.
 *
 * React Aria does the parts a hand-rolled dialog gets wrong: the scrim, focus trapped inside and
 * restored to the trigger on close, Escape to dismiss, a click outside to dismiss, the page behind
 * made inert to a screen reader, and the scroll locked without the page jumping as the bar
 * disappears. `Modal.Close` writes its own `slot="close"` for the same reason `Toast.Close` does.
 *
 * The scrim is the one place in this system where the palette deliberately does not reach, and it
 * says so above.
 */
export const Modal = Object.assign(ModalRoot, {
  Content: ModalContent,
  Title: ModalTitle,
  Description: ModalDescription,
  Footer: ModalFooter,
  Close: ModalClose,
})
